(function(){
const API='https://tablegame.jujuli.com.cn/api',KEY='mq-battle-records-v1';
const ranks=[{min:0,tier:'启蒙',title:'初入棋林'},{min:10,tier:'青铜',title:'棋坛新秀'},{min:30,tier:'白银',title:'街巷好手'},{min:60,tier:'黄金',title:'棋社名家'},{min:100,tier:'铂金',title:'一方棋豪'},{min:180,tier:'钻石',title:'国手风范'},{min:300,tier:'大师',title:'棋道宗师'},{min:500,tier:'传奇',title:'棋圣传说'}];
const points={win:3,draw:1,loss:-1};
function rankFor(score){let rank=ranks[0];for(const r of ranks)if(score>=r.min)rank=r;return {rank,next:ranks[ranks.indexOf(rank)+1]||null}}
function totals(rows){const result={games:0,win:0,draw:0,loss:0,points:0};for(const r of rows){if(!Object.hasOwn(points,r.outcome))continue;result.games+=Number(r.games)||1;result[r.outcome]+=Number(r.games)||1;result.points+=r.points!==undefined?Number(r.points):points[r.outcome]}return result}
window.MQRecordRules={points,ranks,rankFor,totals};
if(typeof document==='undefined')return;
let local=[];try{const a=JSON.parse(localStorage.getItem(KEY));if(Array.isArray(a))local=a.filter(r=>r&&typeof r.match_id==='string'&&Object.hasOwn(points,r.outcome))}catch{}
let displayLimit=20;
let user=null,identityKnown=false,modeFilter='all',panel=null,cloudRows=[],cloudSummary=[],nextCursor=null,hasCloud=false,loading=false,errorText='',requestSerial=0,flushing=false,onlineStamp='';
const owner=()=>identityKnown?(user?.id||'guest'):null;
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(local))}catch{if(typeof toast==='function')toast('本机存储空间不足，请登录后同步战绩')}};
const style=document.createElement('style');style.textContent=`.mq-record-entry{border:0;background:transparent;color:inherit;padding:10px;font:inherit;cursor:pointer;white-space:nowrap}.mq-record-entry svg{width:17px;height:17px;vertical-align:-3px;margin-right:5px}.mq-records{width:min(740px,calc(100vw - 28px));max-height:calc(100dvh - 32px);box-sizing:border-box;overflow:auto;border:1px solid #e0d8c8;border-radius:26px;background:#faf7ef;color:#302f2a;padding:26px;font:14px Microsoft YaHei,system-ui;box-shadow:0 30px 100px #0003}.mq-records::backdrop{background:#302b2555;backdrop-filter:blur(5px)}.mq-record-head{display:flex;align-items:flex-start;justify-content:space-between;gap:10px}.mq-record-head h2{font-size:25px;margin:0 0 7px}.mq-record-head p{color:#938875;font-size:12px;margin:0}.mq-records button{border:0;font:inherit;cursor:pointer;color:inherit;background:#eee7da;padding:10px 14px;border-radius:11px}.mq-records .close{background:transparent;font-size:22px;padding:0 5px}.mq-record-tabs{display:flex;gap:5px;margin:22px 0 16px;padding:4px;background:#eee9df;border-radius:13px}.mq-record-tabs button{flex:1;background:transparent;padding:10px}.mq-record-tabs button.active{background:#fffcf5;box-shadow:0 2px 7px #4b3a2210}.mq-rank-card{border:1px solid #e2d8c7;border-radius:19px;padding:20px;background:linear-gradient(130deg,#fffdf5,#f1e5cf);display:grid;grid-template-columns:1fr auto;gap:12px}.mq-rank-card small{color:#8a7d68}.mq-rank-card h3{margin:6px 0 5px;font-size:21px}.mq-rank-points{font-size:37px;line-height:1.2;letter-spacing:-1px;font-weight:700;text-align:right}.mq-rank-points small{display:block;font-size:11px;font-weight:400;letter-spacing:0}.mq-rank-progress{grid-column:1/-1;height:5px;border-radius:8px;background:#dfd3bf;overflow:hidden}.mq-rank-progress span{display:block;height:100%;background:#ab7b43;transition:width .3s}.mq-rank-next{grid-column:1/-1;margin:0;font-size:11px;color:#8a7d68}.mq-record-metrics{display:grid;grid-template-columns:repeat(4,1fr);margin:18px 0;border:1px solid #e6dfd2;border-radius:15px;padding:14px 0}.mq-record-metrics div{text-align:center;border-right:1px solid #e6dfd2}.mq-record-metrics div:last-child{border:0}.mq-record-metrics strong{display:block;font-size:23px;font-weight:600;margin-bottom:5px}.mq-record-metrics span{font-size:11px;color:#938875}.mq-record-rule,.mq-record-note{font-size:11px;line-height:1.8;color:#978c79;margin:10px 0}.mq-record-error{color:#9d5948}.mq-record-list{list-style:none;margin:14px 0;padding:0}.mq-record-row{padding:14px 0;border-bottom:1px solid #e7e0d4;display:grid;grid-template-columns:1fr auto;gap:7px 12px}.mq-record-row strong{font-weight:500}.mq-record-row small{font-size:11px;color:#948876;line-height:1.6}.mq-record-row .badge{font-size:12px;font-weight:600;text-align:right}.mq-record-row .win{color:#54806a}.mq-record-row .loss{color:#a3604f}.mq-record-row .draw{color:#8a7d68}.mq-record-empty{padding:35px 8px;color:#a19480;text-align:center;line-height:1.9;font-size:12px}.mq-record-actions{display:flex;justify-content:space-between;gap:10px;margin:14px 0}.mq-records button:disabled{opacity:.5;cursor:wait}.mq-rank-guide{margin-top:18px;font-size:12px;color:#8b7e69}.mq-rank-guide summary{cursor:pointer;padding:8px 0}.mq-rank-guide table{width:100%;border-collapse:collapse;margin-top:10px}.mq-rank-guide td{padding:9px 5px;border-bottom:1px solid #e7dfd0;text-align:left}.mq-rank-guide td:last-child{text-align:right}@media(max-width:600px){.mq-records{padding:21px 18px;border-radius:22px}.mq-record-head h2{font-size:22px}.mq-rank-card{padding:16px}.mq-rank-points{font-size:32px}.mq-record-entry{padding:10px 6px;font-size:12px}}`;
document.head.append(style);
const entry=document.createElement('button');entry.className='mq-record-entry';entry.type='button';entry.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M8 3h8v5a4 4 0 0 1-8 0V3Zm0 2H4v2c0 3 2 4 5 4m7-6h4v2c0 3-2 4-5 4m-3 1v5m-4 4h8m-6-4h4v4h-4Z"/></svg>战绩';entry.onclick=()=>open();document.querySelector('.header-right')?.prepend(entry);
async function api(path,data){const c=new AbortController(),timeout=setTimeout(()=>c.abort(),12000);try{const r=await fetch(API+path,{credentials:'include',cache:'no-store',signal:c.signal,...(data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw Object.assign(Error(d.error||'战绩暂时无法同步'),{status:r.status});return d}finally{clearTimeout(timeout)}}
function ownLocal(){const id=user?.id||'guest';return local.filter(r=>r.owner_id===id)}
function filtered(rows){return rows.filter(r=>modeFilter==='all'||r.mode===modeFilter)}
function mergedRows(){const rows=hasCloud?cloudRows.slice():[];const ids=new Set(rows.map(r=>r.mode+':'+r.match_id));for(const r of ownLocal())if((!hasCloud||!!errorText||!r.synced)&&!ids.has(r.mode+':'+r.match_id))rows.push(r);return filtered(rows).sort((a,b)=>b.ended_at-a.ended_at||b.match_id.localeCompare(a.match_id))}
function stats(){const own=ownLocal();return hasCloud?totals([...filtered(cloudSummary),...filtered(own.filter(r=>!r.synced))]):totals(filtered(own))}
function createPanel(){const d=document.createElement('dialog');d.className='mq-records';d.setAttribute('aria-label','我的战绩');d.innerHTML='<div class="mq-record-head"><div><h2>我的战绩</h2><p>每一局，都算数。</p></div><button class="close" type="button" aria-label="关闭战绩">×</button></div><nav class="mq-record-tabs" aria-label="战绩类型"><button data-record-mode="all">全部</button><button data-record-mode="ai">人机战绩</button><button data-record-mode="online">联机战绩</button></nav><div class="mq-rank-card"><div><small class="rank-scope"></small><h3 class="rank-title"></h3><small class="win-rate"></small></div><div class="mq-rank-points"><span></span><small>积分</small></div><div class="mq-rank-progress"><span></span></div><p class="mq-rank-next"></p></div><div class="mq-record-metrics"></div><p class="mq-record-rule">胜 +3 分 · 和 +1 分 · 负 −1 分 · 每局仅结算一次</p><p class="mq-record-note"></p><ul class="mq-record-list"></ul><div class="mq-record-actions"><button class="refresh" type="button">刷新战绩</button><button class="more" type="button">查看更多</button></div><details class="mq-rank-guide"><summary>段位与荣誉称号</summary><table><tbody></tbody></table></details>';
 document.body.append(d);d.querySelector('.close').onclick=()=>d.close();d.addEventListener('close',()=>{d.remove();if(panel===d)panel=null});d.querySelectorAll('[data-record-mode]').forEach(b=>b.onclick=()=>{modeFilter=b.dataset.recordMode;displayLimit=20;render();if(user)refresh()});d.querySelector('.refresh').onclick=()=>{if(user){flush();refresh()}else render()};d.querySelector('.more').onclick=()=>{if(user&&nextCursor)refresh(true);else{displayLimit+=20;render()}};const body=d.querySelector('tbody');for(let i=0;i<ranks.length;i++){const tr=document.createElement('tr'),title=document.createElement('td'),score=document.createElement('td');title.textContent=ranks[i].tier+' · '+ranks[i].title;score.textContent=i?ranks[i].min+'分起':'10分以下';tr.append(title,score);body.append(tr)}return d;
}
function render(){if(!panel)return;const s=stats(),{rank,next}=rankFor(s.points);panel.querySelectorAll('[data-record-mode]').forEach(b=>b.classList.toggle('active',b.dataset.recordMode===modeFilter));panel.querySelector('.rank-scope').textContent=(modeFilter==='ai'?'人机':modeFilter==='online'?'联机':'综合')+' · '+rank.tier+'段';panel.querySelector('.rank-title').textContent=rank.title;panel.querySelector('.win-rate').textContent='胜率 '+(s.games?Math.round(s.win/s.games*100):0)+'%';panel.querySelector('.mq-rank-points span').textContent=String(s.points);panel.querySelector('.mq-rank-progress span').style.width=(next?Math.max(0,Math.min(100,(s.points-rank.min)/(next.min-rank.min)*100)):100)+'%';panel.querySelector('.mq-rank-next').textContent=next?'距「'+next.title+'」还需 '+(next.min-s.points)+' 分':'已获得最高荣誉「棋圣传说」';const metrics=panel.querySelector('.mq-record-metrics');metrics.replaceChildren();for(const [label,value] of [['对局',s.games],['胜',s.win],['和',s.draw],['负',s.loss]]){const cell=document.createElement('div'),strong=document.createElement('strong'),small=document.createElement('span');strong.textContent=String(value);small.textContent=label;cell.append(strong,small);metrics.append(cell)}
 const note=panel.querySelector('.mq-record-note');note.textContent=errorText||(user?(loading?'正在同步账号战绩…':'账号战绩已同步；人机与联机分别记录，也可查看综合积分。'):'未登录：人机战绩保存在本机。登录后新完成的对局可同步到账户。');note.classList.toggle('mq-record-error',!!errorText);
 const list=panel.querySelector('.mq-record-list');list.replaceChildren();const allRows=mergedRows(),rows=allRows.slice(0,displayLimit);if(!rows.length){const li=document.createElement('li');li.className='mq-record-empty';li.textContent=loading?'正在载入战绩…':modeFilter==='online'&&!user?'登录并完成一局联机对弈，开启你的战绩。':'还没有对局记录。下一局，就是新的开始。';list.append(li)}
 const reasons={timeout:'超时判负',resign:'认输结束',opponent_resign:'对手认输',checkmate:'将死',stalemate:'困毙',draw:'双方和棋'};
 for(const r of rows){const li=document.createElement('li');li.className='mq-record-row';const title=document.createElement('strong'),badge=document.createElement('span'),sub=document.createElement('small'),date=document.createElement('small');title.textContent=r.mode==='ai'?'山隐 · Level '+Math.max(1,r.level-1):'对阵 '+r.opponent;badge.className='badge '+r.outcome;badge.textContent=({win:'胜',draw:'和',loss:'负'}[r.outcome])+'  '+(points[r.outcome]>0?'+':'')+points[r.outcome];sub.textContent=(r.mode==='online'?'联机 · 每方 '+(r.time_minutes||15)+' 分钟':'人机对弈')+' · '+(r.reason==='timeout'&&r.outcome==='win'?'对手超时':reasons[r.reason]||'对局结束')+' · '+Math.ceil(r.plies/2)+' 回合';date.textContent=new Date(r.ended_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});date.style.textAlign='right';li.append(title,badge,sub,date);if(window.MQReview?.has(r.match_id)){const review=document.createElement('button');review.type='button';review.className='mq-record-review';review.textContent='复盘分析';review.onclick=()=>window.MQReview.open(r.match_id);li.append(review)}list.append(li)}panel.querySelector('.refresh').disabled=loading;panel.querySelector('.more').hidden=!nextCursor&&allRows.length<=displayLimit;panel.querySelector('.more').disabled=loading;
}
async function refresh(more=false){if(!user){render();return}const id=user.id,serial=++requestSerial;loading=true;errorText='';if(!more){cloudRows=[];nextCursor=null}render();try{const params=new URLSearchParams({mode:modeFilter});const pending=ownLocal().filter(r=>!r.synced).slice(0,20).map(r=>r.match_id);if(pending.length)params.set('pending',pending.join(','));if(more&&nextCursor)params.set('cursor',nextCursor);const d=await api('/chess/records?'+params);if(serial!==requestSerial||id!==user?.id)return;for(const r of ownLocal())if(d.confirmed?.includes(r.match_id))r.synced=true;save();cloudSummary=d.summary;cloudRows=more?[...cloudRows,...d.records]:d.records;if(more)displayLimit+=20;nextCursor=d.nextCursor;hasCloud=true}catch(e){if(serial===requestSerial)errorText='云端暂未连接，已展示本机战绩。联网后可刷新同步。'}finally{if(serial===requestSerial){loading=false;render()}}}
async function flush(){if(flushing||!user)return;const id=user.id,rows=local.filter(r=>r.owner_id===id&&!r.synced).slice(0,20);if(!rows.length)return;flushing=true;try{const result=await api('/chess/ai-results',{ownerId:id,results:rows.map(r=>({gameId:r.match_id,outcome:r.outcome,reason:r.reason,level:r.level,plies:r.plies,startedAt:r.started_at,endedAt:r.ended_at}))});if(user?.id===id)await refresh()}catch{if(panel){errorText='本局已保存在本机，联网后会继续同步。';render()}}finally{flushing=false;if(user?.id===id&&rows.every(r=>r.synced)&&local.some(r=>r.owner_id===id&&!r.synced))setTimeout(flush,2500)}}
let resolveIdentity;const identityReady=new Promise(resolve=>resolveIdentity=resolve);
function setUser(next){const changed=(user?.id||null)!==(next?.id||null);user=next;identityKnown=true;resolveIdentity();if(changed){requestSerial++;hasCloud=false;cloudRows=[];cloudSummary=[];nextCursor=null;onlineStamp='';loading=false;errorText='';render()}if(user){flush();if(panel)refresh()}}
window.addEventListener('mq-auth',e=>setUser(e.detail.user));
async function recordResult(d){try{await identityReady;const who=d.owner===null||d.owner===undefined?(user?.id||'guest'):d.owner;if(local.some(r=>r.owner_id===who&&r.match_id===d.gameId))return;local.push({owner_id:who,mode:'ai',match_id:d.gameId,outcome:d.outcome,reason:d.reason,level:d.level,plies:d.plies,started_at:d.startedAt,ended_at:d.endedAt,opponent:'山隐',synced:false});save();render();window.dispatchEvent(new CustomEvent('mq-records-changed'));await flush()}catch{}}
function open(){if(panel){panel.focus();return}displayLimit=20;panel=createPanel();render();panel.showModal();if(user){refresh();flush()}}
const resultEntry=document.createElement('button');resultEntry.textContent='查看战绩';resultEntry.style.cssText='width:100%;padding:14px;background:transparent;border:0;color:#8a775b;font:inherit;cursor:pointer';resultEntry.onclick=open;document.getElementById('resultDialog')?.append(resultEntry);const gameEntry=document.createElement('button');gameEntry.textContent='我的战绩';gameEntry.onclick=()=>{const more=document.getElementById('gameMore');if(more)more.open=false;open()};document.querySelector('.more-panel')?.append(gameEntry);

async function mastersQualification(){
 await identityReady;const id=user?.id||'guest',isQualified=r=>r.mode==='ai'&&r.outcome==='win'&&Number(r.level)===6&&r.eligible!==false;
 const proofKey='mq-masters-qualification-v1:'+id;try{const proof=JSON.parse(localStorage.getItem(proofKey));if(proof?.owner===id&&proof.level===6&&proof.matchId)return {owner:id,qualified:true}}catch{}
 if(local.some(r=>r.owner_id===id&&isQualified(r)))return {owner:id,qualified:true};
 if(!user)return {owner:id,qualified:false};
 let cursor=null;const seen=new Set();
 try{do{const params=new URLSearchParams({mode:'ai'});if(cursor)params.set('cursor',cursor);const d=await api('/chess/records?'+params);if(id!==(user?.id||'guest'))return mastersQualification();const win=d.records.find(isQualified);if(win){try{localStorage.setItem(proofKey,JSON.stringify({owner:id,level:6,matchId:win.match_id}))}catch{}return {owner:id,qualified:true};}cursor=d.nextCursor;if(cursor){if(seen.has(cursor)||seen.size>=200)throw Error('Incomplete records');seen.add(cursor)}}while(cursor);return {owner:id,qualified:false}}
 catch{return {owner:id,qualified:false,error:'云端战绩暂时无法核验，请联网后重新核验。'}}
}
window.MQRecords={mastersQualification,owner,recordResult,open,refresh,onlineFinished(room){if(room.status!=='ended')return;const stamp=room.matchId+':'+room.resultsRecorded;if(stamp===onlineStamp)return;onlineStamp=stamp;if(user)refresh()}};
if(typeof mode!=='undefined'&&mode==='ai'&&typeof ended!=='undefined'&&ended&&typeof showResult==='function')showResult();
window.addEventListener('online',()=>{flush();if(panel&&user)refresh()});document.addEventListener('visibilitychange',()=>{if(!document.hidden)flush()});
api('/me').then(d=>{if(!identityKnown)setUser(d.user)}).catch(()=>{if(!identityKnown){identityKnown=true;resolveIdentity()}});
})();


